{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "经营周报任务",
  "description": "选择统计周期并上传销售明细和周会纪要，发起一份经营周报任务。",
  "type": "object",
  "required": ["period"],
  "properties": {
    "period": {
      "type": "object",
      "title": "统计周期",
      "description": "要出周报的 ISO 周（周一至周日）。数据覆盖 2026 年第 36 周至第 44 周，超出范围时任务会暂停并告知实际覆盖的日期。",
      "required": ["year", "week"],
      "properties": {
        "year": {
          "type": "integer",
          "title": "年",
          "description": "统计周期所在的年份。",
          "minimum": 2000,
          "maximum": 2100,
          "default": 2026
        },
        "week": {
          "type": "integer",
          "title": "周",
          "description": "ISO 周序号，1 至 53。",
          "minimum": 1,
          "maximum": 53
        }
      }
    },
    "salesFile": {
      "type": "string",
      "title": "销售明细",
      "description": "销售明细文件，建议上传含销售明细、门店信息、商品信息、销售目标四个工作表的 xlsx；只传 csv 会缺少门店和目标信息。未上传时任务会暂停，等待补充。"
    },
    "minutesFiles": {
      "type": "array",
      "title": "周会纪要",
      "description": "经营周会纪要（docx），可上传多份。本周纪要用来解释异常原因，其他周的纪要只用来判断门店停业和说明上周基数。周次按纪要正文标题识别。",
      "items": {
        "type": "string",
        "title": "纪要文件",
        "description": "一份周会纪要文件。"
      }
    },
    "remark": {
      "type": "string",
      "title": "备注",
      "description": "对本次周报的补充要求，会作为写作要求交给员工，例如“摘要先写区域情况”。不能要求更改计算口径。",
      "default": ""
    },
    "allowMissingMinutes": {
      "type": "boolean",
      "title": "无纪要继续",
      "description": "缺少本周纪要时由发起人在暂停卡片上选择，选中后异常原因一律写“原因待核实”。不在表单里手填。",
      "default": false
    },
    "allowPartialPeriod": {
      "type": "boolean",
      "title": "按已有数据继续",
      "description": "统计周期的数据只到周中时由发起人在暂停卡片上选择，选中后周报首页标注“数据不完整”。不在表单里手填。",
      "default": false
    }
  }
}

{
  "ui:order": ["period", "salesFile", "minutesFiles", "remark", "allowMissingMinutes", "allowPartialPeriod"],
  "period": {
    "ui:order": ["year", "week"],
    "year": { "ui:widget": "updown" },
    "week": { "ui:widget": "updown", "ui:placeholder": "例如 44" }
  },
  "salesFile": {
    "ui:widget": "file",
    "ui:options": { "accept": ".xlsx,.csv" },
    "ui:help": "支持 xlsx、csv；推荐 xlsx。"
  },
  "minutesFiles": {
    "ui:widget": "files",
    "ui:options": { "accept": ".docx" },
    "ui:help": "可多选；上传本周和前几周的纪要都可以。"
  },
  "remark": {
    "ui:widget": "textarea",
    "ui:options": { "rows": 3 },
    "ui:placeholder": "选填：对本次周报的补充要求"
  },
  "allowMissingMinutes": { "ui:widget": "hidden" },
  "allowPartialPeriod": { "ui:widget": "hidden" }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "退回意见解读结果",
  "description": "把审核人的退回意见拆成逐条意见，指明每条要改的章节。没有退回意见（首次执行）时提交空清单。是否需要进入待人工处理在顶层判断。",
  "type": "object",
  "additionalProperties": false,
  "required": ["items", "needsHuman"],
  "properties": {
    "items": {
      "type": "array",
      "description": "逐条意见；首次执行或没有退回意见时为空数组。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "comment", "sections", "kind", "action"],
        "properties": {
          "id": { "type": "string", "minLength": 1, "description": "意见编号，按出现顺序写 F1、F2……" },
          "comment": { "type": "string", "minLength": 1, "description": "这一条意见的原话或忠实转述。" },
          "sections": {
            "type": "array",
            "items": { "type": "string" },
            "description": "要改动的章节编号，取自输入中的 sections；确实无法对应到章节时为空数组。"
          },
          "kind": {
            "type": "string",
            "enum": ["narrative", "cause", "calculation_basis", "unclear"],
            "description": "narrative 为改叙述和结构；cause 为改异常原因；calculation_basis 为要求更换计算口径；unclear 为无法判断要求。"
          },
          "action": { "type": "string", "minLength": 1, "description": "打算怎么改，一句话。不写数字。" }
        }
      }
    },
    "needsHuman": {
      "type": "boolean",
      "description": "任何一条意见要求更换计算口径，或与《周报格式要求》冲突、无法照办时为 true，任务进入待人工处理；否则为 false。"
    },
    "needsHumanReason": {
      "type": "string",
      "minLength": 1,
      "description": "needsHuman 为 true 时必填：哪条意见、为什么无法自动处理，写给操作员看。"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "原因匹配结果",
  "description": "为每条异常匹配纪要中的原因，并把纪要中的可核验说法抽成固定格式。是否构成纪要矛盾由程序按阈值判定，这里只抽取。",
  "type": "object",
  "additionalProperties": false,
  "required": ["causes", "claims"],
  "properties": {
    "causes": {
      "type": "array",
      "description": "每条异常恰好一条原因，anomalyId 取自输入的异常清单；与 DraftReport.causes 同形。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["anomalyId", "cause", "level"],
        "properties": {
          "anomalyId": { "type": "string", "minLength": 1, "description": "异常编号，如 store:HZ01、region:华南。" },
          "cause": { "type": "string", "minLength": 1, "description": "原因摘要。沿用上级原因时在末尾加“（区域整体原因）”或“（店型整体原因）”；纪要没提到时只写“原因待核实”。" },
          "level": {
            "type": "string",
            "enum": ["store", "store_type", "region", "company", "unknown"],
            "description": "原因所针对的范围；没有原因时为 unknown。"
          },
          "sourceWeek": {
            "type": "object",
            "additionalProperties": false,
            "required": ["year", "week"],
            "properties": { "year": { "type": "integer" }, "week": { "type": "integer" } },
            "description": "原因出自哪一周的纪要；level 为 unknown 时省略。"
          },
          "quote": { "type": "string", "minLength": 1, "description": "原文摘录，逐字取自所注周次纪要的连续片段；level 为 unknown 时省略。" }
        }
      }
    },
    "claims": {
      "type": "array",
      "description": "纪要中针对数据里有的指标所作的判断（可核验说法）；没有就提交空数组。客流、口感等数据里没有的说法不抽取。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["subject", "metric", "direction", "sourceWeek", "quote"],
        "properties": {
          "subject": {
            "type": "object",
            "additionalProperties": false,
            "required": ["level", "key"],
            "properties": {
              "level": { "type": "string", "enum": ["company", "region", "store", "category"], "description": "说法针对的对象类型。" },
              "key": { "type": "string", "minLength": 1, "description": "对象的业务键：全公司写 company；区域写区域名，如 华南；门店写门店编码，如 SH02；品类写品类名。" }
            }
          },
          "metric": { "type": "string", "enum": ["wow"], "description": "指标。目前只核验实收环比，纪要里“销售上升/下降/持平”都归为 wow。" },
          "direction": { "type": "string", "enum": ["flat", "up", "down"], "description": "纪要说的方向：持平、上升、下降。" },
          "magnitude": { "type": "number", "minimum": 0, "description": "纪要给出的幅度，按小数写（两成写 0.2，约七成写 0.7）；纪要没给幅度时省略。" },
          "sourceWeek": {
            "type": "object",
            "additionalProperties": false,
            "required": ["year", "week"],
            "properties": { "year": { "type": "integer" }, "week": { "type": "integer" } },
            "description": "说法出自哪一周的纪要。"
          },
          "quote": { "type": "string", "minLength": 1, "description": "原文摘录，逐字取自所注周次纪要的连续片段。" }
        }
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "周报草稿",
  "description": "撰写周报叙述的结果，结构与契约中的 DraftReport 一致。叙述中的数字只写槽位，如 {{company.wow}}。",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "sections", "causes"],
  "properties": {
    "title": {
      "type": "string",
      "minLength": 1,
      "description": "周报标题，如“经营周报（2026 年第 44 周）”。"
    },
    "sections": {
      "type": "array",
      "minItems": 1,
      "description": "章节，顺序与 qc.yaml 中的章节一致。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "heading"],
        "anyOf": [
          { "required": ["paragraphs"], "properties": { "paragraphs": { "type": "array", "items": { "type": "string" } } } },
          { "required": ["bullets"], "properties": { "bullets": { "type": "array", "items": { "type": "string" } } } }
        ],
        "properties": {
          "id": { "type": "string", "minLength": 1, "description": "章节编号，取自输入中的 structure.sections。" },
          "heading": { "type": "string", "minLength": 1, "description": "章节标题，与 structure.sections 中的标题一字不差。" },
          "paragraphs": { "type": "array", "items": { "type": "string" }, "description": "正文段落，数字只写槽位。" },
          "bullets": { "type": "array", "items": { "type": "string" }, "description": "要点列表，数字只写槽位。" }
        }
      }
    },
    "causes": {
      "type": "array",
      "description": "原因匹配结果，原样取自 match_causes 的结果，每条异常一条。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["anomalyId", "cause", "level"],
        "properties": {
          "anomalyId": { "type": "string", "minLength": 1, "description": "异常编号，如 store:HZ01、region:华南。" },
          "cause": { "type": "string", "minLength": 1, "description": "原因摘要；纪要没提到时写“原因待核实”。" },
          "level": {
            "type": "string",
            "enum": ["store", "store_type", "region", "company", "unknown"],
            "description": "原因层级。"
          },
          "sourceWeek": {
            "type": "object",
            "additionalProperties": false,
            "required": ["year", "week"],
            "properties": { "year": { "type": "integer" }, "week": { "type": "integer" } },
            "description": "原因出自哪一周的纪要。"
          },
          "quote": { "type": "string", "minLength": 1, "description": "原文摘录，必须是所注周次纪要原文的连续片段。" }
        }
      }
    },
    "revisionNotes": {
      "type": "array",
      "description": "仅重做时提供：逐条退回意见对应的修改说明。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["comment", "sections", "change"],
        "properties": {
          "comment": { "type": "string", "minLength": 1, "description": "对应的退回意见。" },
          "sections": { "type": "array", "items": { "type": "string" }, "description": "改动的章节编号。" },
          "change": { "type": "string", "minLength": 1, "description": "改了什么。" }
        }
      }
    },
    "contradictionRefs": {
      "type": "array",
      "description": "引用的纪要矛盾 id：写进“异常与原因”章节的每条矛盾都要列出；没有矛盾时提交空数组。",
      "items": { "type": "string", "minLength": 1 }
    }
  }
}
